const nextBatchCodeNo = `-- name: NextBatchCodeNo :one

INSERT INTO batch_code_counters (user_id, prefix, last_no)
VALUES ($1, $2, 1)
ON CONFLICT (user_id, prefix) DO UPDATE SET last_no = batch_code_counters.last_no + 1
RETURNING last_no
`

type NextBatchCodeNoParams struct {
	UserID string
	Prefix string
}

// Every query names user_id explicitly, in addition to row level security.
func (q *Queries) NextBatchCodeNo(ctx context.Context, arg NextBatchCodeNoParams) (int32, error) {
	row := q.db.QueryRow(ctx, nextBatchCodeNo, arg.UserID, arg.Prefix)
	var last_no int32
	err := row.Scan(&last_no)
	return last_no, err
}

